code="from flask import Flask\nimport os, threading, time, requests\napp=Flask(__name__)\nTOKEN=os.environ.get('TELEGRAM_BOT_TOKEN','').strip()\nCHAT=os.environ.get('TELEGRAM_CHAT_ID','').strip()\ndef send(msg):\n    print(f'SENDING TO TG: {CHAT}')\n    try:\n        url=f'https://api.telegram.org/bot{TOKEN}/sendMessage'\n        r=requests.post(url, json={'chat_id': CHAT, 'text': msg}, timeout=15)\n        print(f'TELEGRAM RESULT: {r.status_code} {r.text[:200]}')\n    except Exception as e:\n        print(f'TG FAIL: {e}')\ndef loop():\n    time.sleep(3)\n    send('✅ Ross Bot LIVE on Render! Telegram working!')\n    while True:\n        time.sleep(60)\napp.add_url_rule('/', 'home', lambda: 'Ross Bot - LIVE')\napp.add_url_rule('/health', 'health', lambda: 'OK')\nif __name__=='__main__':\n    threading.Thread(target=loop, daemon=True).start()\n    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))\n"
exec(code)
